<?php
$diagnosisFields=['chief_complaint'=>'Motivo de consulta','medical_history'=>'Antecedentes médicos relevantes','dental_history'=>'Antecedentes odontológicos','facial_evaluation'=>'Evaluación facial','intraoral_evaluation'=>'Evaluación intraoral','molar_relation'=>'Relación molar','canine_relation'=>'Relación canina','angle_class'=>'Clasificación de Angle','overbite_mm'=>'Sobremordida (mm)','overjet_mm'=>'Resalte (mm)','crowding_mm'=>'Apiñamiento (mm)','spacing_mm'=>'Espacios dentales (mm)','midline'=>'Línea media','bite'=>'Tipo de mordida','periodontal_evaluation'=>'Evaluación periodontal','imaging'=>'Estudios radiográficos y cefalométricos','clinical_diagnosis'=>'Diagnóstico clínico','objectives'=>'Objetivos del tratamiento','prognosis'=>'Pronóstico','observations'=>'Observaciones profesionales'];
?>
<div class="orth-section-intro"><div><h3>Diagnóstico ortodóntico</h3><p>Evaluaciones versionadas, con fecha y profesional responsable.</p></div><?php if($diagnoses): ?><span class="orth-status"><?= count($diagnoses) ?> <?= count($diagnoses)===1?'evaluación':'evaluaciones' ?></span><?php endif; ?></div>
<?php if($canWrite): ?><details class="panel orth-form-panel"<?= !$diagnoses?' open':'' ?>><summary><?= icon('tooth',18) ?><span><?= $diagnoses?'Registrar una nueva evaluación':'Completar la evaluación inicial' ?></span><small>El diagnóstico previo se conserva</small></summary><div class="orth-section-heading"><div><span class="orth-kicker"><?= $diagnoses?'NUEVA VERSIÓN DE LA EVALUACIÓN':'EVALUACIÓN INICIAL' ?></span><h3>Registro clínico</h3></div></div><form method="post" class="form-grid orth-panel-body orth-diagnosis-form" data-orth-dirty data-loading><?php $orthoFields('diagnosis',$case); ?><input type="hidden" name="previous_id" value="<?= (int)($diagnoses[0]['id'] ?? 0) ?>"><?php field('evaluation_date','Fecha de evaluación',$diagnosis['evaluation_date'] ?? date('Y-m-d'),'date',true,'max="'.date('Y-m-d').'"'); ?><p class="orth-help">Completa únicamente los hallazgos evaluados. Los campos vacíos no generan conclusiones automáticas.</p><h4 class="orth-form-divider full">Consulta y antecedentes</h4><?php area('chief_complaint','Motivo de consulta',$diagnosis['chief_complaint'] ?? '',true); area('medical_history','Antecedentes médicos relevantes',$diagnosis['medical_history'] ?? $patient['medical_history'] ?? $patient['record']['medical_history'] ?? ''); area('dental_history','Antecedentes odontológicos',$diagnosis['dental_history'] ?? $patient['dental_history'] ?? $patient['record']['dental_history'] ?? ''); ?><h4 class="orth-form-divider full">Evaluación clínica</h4><?php area('facial_evaluation','Evaluación facial',$diagnosis['facial_evaluation'] ?? ''); area('intraoral_evaluation','Evaluación intraoral',$diagnosis['intraoral_evaluation'] ?? ''); field('molar_relation','Relación molar',$diagnosis['molar_relation'] ?? '','text',false); field('canine_relation','Relación canina',$diagnosis['canine_relation'] ?? '','text',false); choose('angle_class','Clasificación de Angle',['I'=>'Clase I','II_div1'=>'Clase II · división 1','II_div2'=>'Clase II · división 2','III'=>'Clase III','not_assessed'=>'No evaluada'],$diagnosis['angle_class'] ?? '',false); field('midline','Línea media',$diagnosis['midline'] ?? '','text',false); field('bite','Mordida abierta, cruzada, profunda u otra',$diagnosis['bite'] ?? '','text',false); ?><h4 class="orth-form-divider full">Mediciones registradas</h4><?php foreach(['overbite_mm'=>'Sobremordida (mm)','overjet_mm'=>'Resalte (mm)','crowding_mm'=>'Apiñamiento (mm)','spacing_mm'=>'Espacios dentales (mm)'] as $name=>$title)field($name,$title,$diagnosis[$name] ?? '','number',false,'step="0.1" min="-50" max="50"'); ?><h4 class="orth-form-divider full">Estudios y conclusión profesional</h4><?php area('periodontal_evaluation','Evaluación periodontal',$diagnosis['periodontal_evaluation'] ?? ''); area('imaging','Estudios radiográficos y cefalométricos',$diagnosis['imaging'] ?? ''); area('clinical_diagnosis','Diagnóstico clínico',$diagnosis['clinical_diagnosis'] ?? '',true); area('objectives','Objetivos del tratamiento',$diagnosis['objectives'] ?? ''); area('prognosis','Pronóstico',$diagnosis['prognosis'] ?? ''); area('observations','Observaciones profesionales',$diagnosis['observations'] ?? ''); ?><div class="orth-info full"><?= icon('shield',18) ?><span>Al guardar se crea una evaluación nueva y se conserva el contenido de las anteriores. Las clasificaciones y medidas son responsabilidad del profesional.</span></div><button class="button full">Guardar evaluación clínica</button></form></details><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><h3>Evaluaciones anteriores</h3></div><?php if(!$diagnoses): $orthoEmpty('Sin diagnóstico registrado','La evaluación del profesional se mostrará aquí.','tooth'); else: ?><div class="orth-records"><?php foreach($diagnoses as $index=>$entry): $data=$entry['data'] ?? []; ?><details class="orth-record"<?= !$index?' open':'' ?>><summary><span><strong>Evaluación <?= count($diagnoses)-$index ?></strong><small><?= $orthoDate($entry['evaluation_date'] ?? $data['evaluation_date'] ?? null) ?> · <?= e($entry['author'] ?? $entry['professional'] ?? '') ?></small></span><span class="orth-status"><?= $index===0?'Última versión':'Histórica' ?></span></summary><div class="orth-record-body"><dl class="orth-definition-list"><?php foreach($diagnosisFields as $key=>$title): if(isset($data[$key]) && $data[$key]!==''): ?><div><dt><?= e($title) ?></dt><dd><?= nl2br(e($data[$key])) ?></dd></div><?php endif; endforeach; ?></dl></div></details><?php endforeach; ?></div><?php endif; ?></section>
